ALTER TABLE workflows ADD COLUMN archived boolean NOT NULL DEFAULT false;
ALTER TABLE executions ADD COLUMN parent_id uuid REFERENCES executions(id);
ALTER TABLE executions ADD COLUMN parent_node_id text;
ALTER TABLE executions ADD COLUMN child_index integer;
ALTER TABLE executions ADD COLUMN root_id uuid;
ALTER TABLE executions ADD COLUMN depth integer NOT NULL DEFAULT 0;
ALTER TABLE executions ADD COLUMN effect_count integer NOT NULL DEFAULT 0;
ALTER TABLE executions ADD COLUMN effect_limit integer NOT NULL DEFAULT 100;
CREATE UNIQUE INDEX execution_child_identity ON executions(parent_id,parent_node_id,child_index) WHERE parent_id IS NOT NULL;
ALTER TABLE steps ADD COLUMN state jsonb NOT NULL DEFAULT '{}';
ALTER TABLE steps ADD COLUMN retry_attempts integer NOT NULL DEFAULT 0;
CREATE TABLE approvals (id uuid PRIMARY KEY, execution_id uuid NOT NULL REFERENCES executions(id), node_id text NOT NULL, owner_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, status text NOT NULL DEFAULT 'PENDING', decision_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz, UNIQUE(execution_id,node_id));
CREATE TABLE data_tables (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE data_records (table_id uuid NOT NULL REFERENCES data_tables(id), record_key text NOT NULL, value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(table_id,record_key));
CREATE TABLE effect_events (id bigserial PRIMARY KEY, root_id uuid NOT NULL REFERENCES executions(id), execution_id uuid NOT NULL REFERENCES executions(id), node_id text NOT NULL, kind text NOT NULL, target text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX effect_events_root ON effect_events(root_id);
CREATE INDEX approvals_owner ON approvals(owner_id,status);
DROP INDEX executions_ready;
CREATE INDEX executions_ready ON executions(next_attempt_at) WHERE status IN ('QUEUED','RUNNING','RETRYING','WAITING');
